-- Read-only post-retirement verification. Every violation count must be zero.
select 'retired_categories' check_name,count(*) violations from public.categories where lower(replace(name,chr(8217),chr(39)))='woman''s meeting'
union all select 'retirement_constraint',count(*)from(values(1))v(n)where not exists(select 1 from pg_constraint where conrelid='public.categories'::regclass and conname='categories_no_retired_womans_meeting'and convalidated)
union all select 'retired_fine_candidates',count(*)from public.task_fine_candidates where lower(replace(category_name,chr(8217),chr(39)))='woman''s meeting'
union all select 'retired_issued_fines',count(*)from public.task_fines where lower(replace(category_name,chr(8217),chr(39)))='woman''s meeting'
union all select 'retired_cutoffs',count(*)from(values(1))v(n)where public.task_app_fine_cutoff('Woman''s Meeting','2026-10-15','23:50')is not null or public.task_app_history_expires('Woman''s Meeting',now(),null,'{}')is not null
union all select 'fine_cutoffs',count(*)from(values('Sunday Service','2026-10-11'::date,'2026-10-12'::date),('Healing Meeting','2026-10-14'::date,'2026-10-15'::date),('Revival Meeting','2026-10-16'::date,'2026-10-17'::date),('Special Meeting','2026-10-17'::date,'2026-10-18'::date))v(category,meeting_day,end_day)where public.task_app_fine_cutoff(category,meeting_day,'23:50')is distinct from((end_day+time '05:00')at time zone 'Asia/Kolkata')
union all select 'history_cutoffs',count(*)from(values('Sunday Service','2026-10-11'::date,'2026-10-12'::date),('Healing Meeting','2026-10-14'::date,'2026-10-15'::date),('Revival Meeting','2026-10-16'::date,'2026-10-17'::date),('Special Meeting','2026-10-17'::date,'2026-10-18'::date))v(category,meeting_day,end_day)where public.task_app_history_expires(category,(meeting_day+time '12:00')at time zone 'Asia/Kolkata',meeting_day,'{}')is distinct from((end_day+time '23:50')at time zone 'Asia/Kolkata')
union all select 'private_table_access',count(*)from(values('public.account_member_absences'),('public.task_coverage_claims'),('public.task_fines'),('public.task_fine_candidates'),('public.member_task_completions'),('public.member_completion_totals'))t(name)cross join(values('anon'),('authenticated'),('service_role'))r(role)where has_table_privilege(role,name,'SELECT,INSERT,UPDATE,DELETE')
union all select 'rpc_execute_access',count(*)from(values('public.task_app_setup(text,text)'),('public.task_app_mark_absent(uuid,date,boolean)'))f(signature)cross join(values('anon'),('authenticated'),('service_role'))r(role)where has_function_privilege(role,signature,'EXECUTE')is distinct from(role='authenticated');
